const assert = require('node:assert/strict');

const { EventService } = require('../.build/service');

// Builds a fake Source (see src/source.ts) whose lease replays a scripted
// stream of strings (null ends it) and can fail on read or close. Every
// open/read/close is logged and counted.
function createSource(options = {}) {
  const queue = [...(options.values ?? [])];
  const log = options.log ?? [];
  const state = { opens: 0, reads: 0, closes: 0 };
  const source = {
    open: async () => {
      state.opens += 1;
      log.push('open');
      return {
        read: async () => {
          state.reads += 1;
          log.push('read');
          if (options.readError) throw options.readError;
          const value = queue.shift();
          return value === undefined ? null : value;
        },
        close: async () => {
          state.closes += 1;
          log.push('close');
          if (options.closeError) throw options.closeError;
        },
      };
    },
  };
  return { source, state, log };
}

const tests = [];

tests.push(['closes the lease once on normal exhaustion and keeps record order', async () => {
  const log = [];
  const { source, state } = createSource({ values: ['a', 'b', 'c'], log });
  const service = new EventService(source);
  const found = [];
  for await (const value of service.stream()) found.push(value);
  assert.deepEqual(found, ['A', 'B', 'C']);
  assert.equal(state.opens, 1);
  assert.equal(state.reads, 4); // three records + the read establishing exhaustion
  assert.equal(state.closes, 1);
  assert.deepEqual(log, ['open', 'read', 'read', 'read', 'read', 'close']);
}]);

tests.push(['does not open the lease before the first iteration', async () => {
  const { source, state } = createSource({ values: ['a'] });
  const service = new EventService(source);
  const generator = service.stream();
  assert.equal(state.opens, 0, 'open() must wait for the first iteration');
  const first = await generator.next();
  assert.deepEqual(first, { value: 'A', done: false });
  assert.equal(state.opens, 1);
  const closed = await generator.return();
  assert.deepEqual(closed, { value: undefined, done: true });
  assert.equal(state.reads, 1);
  assert.equal(state.closes, 1);
}]);

tests.push(['returning an unopened generator opens and closes nothing', async () => {
  const { source, state } = createSource({ values: ['a'] });
  const service = new EventService(source);
  const result = await service.stream().return();
  assert.deepEqual(result, { value: undefined, done: true });
  assert.equal(state.opens, 0);
  assert.equal(state.reads, 0);
  assert.equal(state.closes, 0);
}]);

tests.push(['throwing into an unopened generator opens and closes nothing', async () => {
  const injected = new Error('injected');
  const { source, state } = createSource({ values: ['a'] });
  const service = new EventService(source);
  await assert.rejects(() => service.stream().throw(injected), (error) => error === injected);
  assert.equal(state.opens, 0);
  assert.equal(state.reads, 0);
  assert.equal(state.closes, 0);
}]);

tests.push(['issues one read per next() without reading ahead', async () => {
  const { source, state } = createSource({ values: ['a', 'b'] });
  const service = new EventService(source);
  const generator = service.stream();
  assert.deepEqual(await generator.next(), { value: 'A', done: false });
  assert.equal(state.reads, 1);
  assert.deepEqual(await generator.next(), { value: 'B', done: false });
  assert.equal(state.reads, 2);
  assert.deepEqual(await generator.next(), { value: undefined, done: true });
  assert.equal(state.reads, 3); // only the read establishing exhaustion produced no record
  assert.equal(state.closes, 1);
}]);

tests.push(['closes the lease once when the consumer breaks out of the loop', async () => {
  const log = [];
  const { source, state } = createSource({ values: ['a', 'b'], log });
  const service = new EventService(source);
  const found = [];
  for await (const value of service.stream()) {
    found.push(value);
    break;
  }
  assert.deepEqual(found, ['A']);
  assert.deepEqual(log, ['open', 'read', 'close']);
  assert.equal(state.closes, 1);
  assert.equal(state.reads, 1); // no read ahead of the consumer's break
}]);

tests.push(['closes the lease once on an explicit return() mid-stream', async () => {
  const { source, state } = createSource({ values: ['a', 'b'] });
  const service = new EventService(source);
  const generator = service.stream();
  await generator.next();
  const closed = await generator.return();
  assert.deepEqual(closed, { value: undefined, done: true });
  assert.equal(state.reads, 1);
  assert.equal(state.closes, 1);
}]);

tests.push(['closes the lease once on a source read failure and preserves the read error', async () => {
  const readError = new Error('read failed');
  const { source, state } = createSource({ readError });
  const service = new EventService(source);
  const generator = service.stream();
  await assert.rejects(() => generator.next(), (error) => error === readError);
  assert.equal(state.closes, 1);
  const after = await generator.next();
  assert.deepEqual(after, { value: undefined, done: true });
  assert.equal(state.closes, 1, 'the lease must not be closed twice');
  assert.equal(state.reads, 1, 'a completed generator must not read again');
}]);

tests.push(['a read failure wins over a close failure', async () => {
  const readError = new Error('read failed');
  const closeError = new Error('close failed');
  const { source, state } = createSource({ readError, closeError });
  const service = new EventService(source);
  await assert.rejects(() => service.stream().next(), (error) => error === readError);
  assert.equal(state.closes, 1);
}]);

tests.push(['closes the lease once on a mapper failure and preserves the mapper error', async () => {
  const mapperError = new Error('mapper failed');
  const mapper = () => { throw mapperError; };
  const { source, state } = createSource({ values: ['a'] });
  const service = new EventService(source, mapper);
  const generator = service.stream();
  await assert.rejects(() => generator.next(), (error) => error === mapperError);
  assert.equal(state.closes, 1);
  assert.equal(state.reads, 1);
}]);

tests.push(['a mapper failure wins over a close failure', async () => {
  const mapperError = new Error('mapper failed');
  const mapper = () => { throw mapperError; };
  const { source, state } = createSource({ values: ['a'], closeError: new Error('close failed') });
  const service = new EventService(source, mapper);
  await assert.rejects(() => service.stream().next(), (error) => error === mapperError);
  assert.equal(state.closes, 1);
}]);

tests.push(['propagates a close failure on normal exhaustion', async () => {
  const closeError = new Error('close failed');
  const { source, state } = createSource({ values: ['a'], closeError });
  const service = new EventService(source);
  const generator = service.stream();
  assert.deepEqual(await generator.next(), { value: 'A', done: false });
  await assert.rejects(() => generator.next(), (error) => error === closeError);
  assert.equal(state.closes, 1);
  assert.deepEqual(await generator.next(), { value: undefined, done: true });
  assert.equal(state.closes, 1, 'the lease must not be closed twice');
}]);

tests.push(['propagates a close failure when the consumer breaks out of the loop', async () => {
  const closeError = new Error('close failed');
  const { source, state } = createSource({ values: ['a', 'b'], closeError });
  const service = new EventService(source);
  await assert.rejects(async () => {
    for await (const value of service.stream()) break;
  }, (error) => error === closeError);
  assert.equal(state.closes, 1);
  assert.equal(state.reads, 1);
}]);

tests.push(['closes the lease once on a consumer-injected throw and preserves the injected error', async () => {
  const injected = new Error('injected');
  const { source, state } = createSource({ values: ['a', 'b'] });
  const service = new EventService(source);
  const generator = service.stream();
  await generator.next();
  await assert.rejects(() => generator.throw(injected), (error) => error === injected);
  assert.deepEqual(await generator.next(), { value: undefined, done: true });
  assert.equal(state.closes, 1);
  assert.equal(state.reads, 1);
}]);

tests.push(['a consumer-injected throw wins over a close failure', async () => {
  const injected = new Error('injected');
  const { source, state } = createSource({ values: ['a', 'b'], closeError: new Error('close failed') });
  const service = new EventService(source);
  const generator = service.stream();
  await generator.next();
  await assert.rejects(() => generator.throw(injected), (error) => error === injected);
  assert.equal(state.closes, 1);
}]);

async function main() {
  const failures = [];
  for (const [name, test] of tests) {
    try {
      await test();
      console.log(`ok - ${name}`);
    } catch (error) {
      failures.push({ name, error });
      console.log(`not ok - ${name}`);
      console.error(`    ${error && error.stack ? error.stack : error}`);
    }
  }
  if (failures.length > 0) {
    throw new Error(`${failures.length} of ${tests.length} stream checks failed`);
  }
  console.log(`all ${tests.length} stream checks passed`);
}

module.exports = main();

